const body = $input.first().json.data || $input.first().json.body || JSON.stringify($input.first().json);
const match = body.match(/strava\.com\/activities\/(\d+)/);

if (!match) {
  throw new Error('HTML içinde Strava aktivite ID bulunamadı');
}

return [{ json: { activity_id: match[1] } }];

const item = $input.first().json;
const athleteAge = item.age;
const restingHr = item.resting_hr;

const maxHr = 220 - athleteAge;
const hrReserve = maxHr - restingHr;

const zone1Low = Math.floor((hrReserve * 0.50) + restingHr);
const zone1High = Math.floor((hrReserve * 0.60) + restingHr);
const zone2Low = zone1High + 1;
const zone2High = Math.floor((hrReserve * 0.70) + restingHr);
const zone3Low = zone2High + 1;
const zone3High = Math.floor((hrReserve * 0.80) + restingHr);
const zone4Low = zone3High + 1;
const zone4High = Math.floor((hrReserve * 0.90) + restingHr);
const zone5Low = zone4High + 1;
const zone5High = maxHr;

return [{ json: {
  zone1_low: zone1Low, zone1_high: zone1High,
  zone2_low: zone2Low, zone2_high: zone2High,
  zone3_low: zone3Low, zone3_high: zone3High,
  zone4_low: zone4Low, zone4_high: zone4High,
  zone5_low: zone5Low, zone5_high: zone5High,
} }];

const plan = $('AI Agent1').first().json.output;
const userInfo = $('Get row(s) in sheet').first().json;
const zoneInfo = $('user sheet\'inde ilgili kullaniciyi cek').first().json;
const telegramUser = $('Telegram Trigger').first().json;

const firstName = telegramUser.message.from.first_name || telegramUser.message.chat.first_name || "Kullanıcı";
const dynamicTitle = `${firstName} — ${plan.toplam_hafta} Haftalık Antrenman Planı`;

const zoneLabels = {
  zone1: "Zone 1 — Toparlanma",
  zone2: "Zone 2 — Aerobik / Kolay Koşu",
  zone3: "Zone 3 — Tempo",
  zone4: "Zone 4 — Eşik (Threshold)",
  zone5: "Zone 5 — VO2 Max / Anaerobik"
};

const blocks = [];

blocks.push({
  object: "block", type: "heading_1",
  heading_1: { rich_text: [{ text: { content: dynamicTitle } }] }
});
blocks.push({
  object: "block", type: "paragraph",
  paragraph: { rich_text: [{ text: { content: plan.plan_ozeti } }] }
});

blocks.push({
  object: "block", type: "heading_2",
  heading_2: { rich_text: [{ text: { content: "Nabız Bölgeleri (Karvonen Formülü)" } }] }
});
blocks.push({
  object: "block", type: "callout",
  callout: {
    rich_text: [{ text: { content: `Dinlenik Nabız: ${userInfo.resting_hr ?? "?"} bpm` } }],
    icon: { emoji: "❤️" }
  }
});
for (const [key, label] of Object.entries(zoneLabels)) {
  const range = (zoneInfo[key] || "").toString().replace("/", "–");
  blocks.push({
    object: "block", type: "bulleted_list_item",
    bulleted_list_item: { rich_text: [{ text: {
      content: `${label}: ${range} bpm`
    } }] }
  });
}

for (let i = 0; i < plan.haftalik_plan.length; i++) {
  const hafta = plan.haftalik_plan[i];
  const nextHafta = plan.haftalik_plan[i + 1];
  const startWeek = hafta.hafta;
  const endWeek = nextHafta ? nextHafta.hafta - 1 : plan.toplam_hafta;
  const weekLabel = startWeek === endWeek ? `Hafta ${startWeek}` : `Hafta ${startWeek}–${endWeek}`;

  blocks.push({
    object: "block", type: "heading_2",
    heading_2: { rich_text: [{ text: { content: `${weekLabel} — ${hafta.faz} (${hafta.haftalik_hedef_km} km/hafta)` } }] }
  });

  if (startWeek !== endWeek) {
    blocks.push({
      object: "block", type: "callout",
      callout: {
        rich_text: [{ text: { content: `Bu antrenman şablonu ${weekLabel} boyunca tekrarlanır (hacim hafif artırılarak).` } }],
        icon: { emoji: "🔁" }
      }
    });
  }

  for (const a of hafta.antrenmanlar) {
    blocks.push({
      object: "block", type: "bulleted_list_item",
      bulleted_list_item: { rich_text: [{ text: {
        content: `${a.gun} — ${a.tur} (${a.sure_dk} dk, ${a.hedef_zone}): ${a.aciklama}`
      } }] }
    });
  }
}

blocks.push({
  object: "block", type: "heading_2",
  heading_2: { rich_text: [{ text: { content: "Riskler" } }] }
});
for (const r of plan.riskler) {
  blocks.push({
    object: "block", type: "bulleted_list_item",
    bulleted_list_item: { rich_text: [{ text: { content: r } }] }
  });
}

blocks.push({
  object: "block", type: "callout",
  callout: {
    rich_text: [{ text: { content: `Belirsizlik: ${plan.belirsizlik}` } }],
    icon: { emoji: "⚠️" }
  }
});

blocks.push({
  object: "block", type: "heading_2",
  heading_2: { rich_text: [{ text: { content: "Kaynaklar" } }] }
});
for (const k of plan.kaynaklar) {
  blocks.push({
    object: "block", type: "bulleted_list_item",
    bulleted_list_item: { rich_text: [{ text: { content: k } }] }
  });
}

return [{ json: {
  title: dynamicTitle,
  blocks: blocks
} }];

