const streams = $("activity_id'den api ile antrenmani cek").item.json;
const hrData = (streams.heartrate && streams.heartrate.data) || [];
const speedData = (streams.velocity_smooth && streams.velocity_smooth.data) || [];

const result = { ...$input.first().json };  // onceki node ciktisini koru
result.hr_drift_pct = null;                  // varsayilan: hesaplanamadi

const avg = (arr) => arr.reduce((a, b) => a + b, 0) / arr.length;

if (hrData.length === speedData.length && hrData.length >= 20) {
  const mid = Math.floor(hrData.length / 2);
  const hr1 = hrData.slice(0, mid).filter((h) => h !== null && h !== undefined);
  const hr2 = hrData.slice(mid).filter((h) => h !== null && h !== undefined);
  const sp1 = speedData.slice(0, mid).filter((s) => s !== null && s !== undefined).map((s) => s * 3.6);
  const sp2 = speedData.slice(mid).filter((s) => s !== null && s !== undefined).map((s) => s * 3.6);

  if (hr1.length && hr2.length && sp1.length && sp2.length) {
    const avgHr1 = avg(hr1), avgHr2 = avg(hr2);
    const avgSp1 = avg(sp1), avgSp2 = avg(sp2); // km/h

    if (avgSp1 >= 3.0 && avgSp2 >= 3.0 && avgHr1 > 0 && avgHr2 > 0) {
      const ef1 = avgSp1 / avgHr1; // efficiency factor: hiz/nabiz
      const ef2 = avgSp2 / avgHr2;
      // pozitif % = 2. yaride ayni nabizla daha az hiz uretiliyor -> drift
      result.hr_drift_pct = Math.round(((ef1 - ef2) / ef1 * 100) * 100) / 100;
    }
  }
}

return [{ json: result }];
